package gadomancymodern.client;
import com.mojang.blaze3d.vertex.*;
import gadomancymodern.aura.AuraPylonEntity;
import net.minecraft.client.Minecraft;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
/** Original three arbitrary-plane trails and shaded FXWisp particles. */
@Mod.EventBusSubscriber(modid="gadomancy",value=Dist.CLIENT)
public class AuraPylonEffects {
    protected static final java.util.Map<AuraPylonEntity,Orbits> ORBITS=new java.util.IdentityHashMap<>();
    protected static final java.util.List<ColoredWisp> WISPS=new java.util.ArrayList<>();protected static Object world;
    protected static void reset(){var now=Minecraft.getInstance().level;if(world!=now){world=now;ORBITS.clear();WISPS.clear();}}
    public static void tick(AuraPylonEntity tile){reset();if(!tile.formed)return;var level=tile.getLevel();if(tile.cap()){var orbital=ORBITS.computeIfAbsent(tile,Orbits::new);orbital.age++;return;}if(tile.index==0&&tile.amount>0&&tile.ticks%2==1){var master=tile.section(2);if(master!=null)tc4revival.aspect.TCAspects.catalog().find(tile.aspect).ifPresent(a->LegacyEssentiaTrails.add(tile.getBlockPos().getCenter().add(0,-.3,0),master.getBlockPos().getCenter().add(0,1.2,0),a.color(),1,5));}}
    public static void visible(AuraPylonEntity tile,float partial){reset();if(!tile.formed||Minecraft.getInstance().isPaused())return;var orbital=ORBITS.computeIfAbsent(tile,Orbits::new);orbital.lastSeen=tile.getLevel().getGameTime();var random=tile.getLevel().random;var aspect=tc4revival.aspect.TCAspects.catalog().find(tile.aspect).orElse(tc4revival.aspect.TCAspects.catalog().require("tempestas"));int color=aspect.color();boolean dark=java.util.Set.of("perditio","tenebrae","exanimis").contains(aspect.tag());var center=tile.getBlockPos().getCenter().add(0,.2,0);
        if(random.nextInt(12)==0)addWisp(center,color,.5f,dark);if(random.nextInt(20)==0)addWisp(center,new java.awt.Color(color).darker().darker().getRGB(),.25f,dark);
        var input=tile.section(0);if(input==null||input.amount<=0)return;for(int i=0;i<3;i++){var point=orbital.point(i,center);AuraCoreEffects.addAlpha(point,color,.2f,24,85);if(random.nextInt(3)==0){int subColor=random.nextBoolean()?new java.awt.Color(color).brighter().brighter().getRGB():color;AuraCoreEffects.addAlpha(point.add(AuraCoreEffects.offset(random,.2)),subColor,random.nextBoolean()?.1f:.2f,18,85);}}
    }
    protected static void addWisp(Vec3 center,int color,float size,boolean dark){var level=Minecraft.getInstance().level;if(level==null||Minecraft.getInstance().gameRenderer.getMainCamera().getPosition().distanceToSqr(center)>gadomancymodern.ClientConfig.limitSquared(Minecraft.useFancyGraphics()?2500:625))return;var r=level.random;WISPS.add(new ColoredWisp(level,center.add(.05,0,.05),center.add(-.2+r.nextFloat()*.4,0,-.2+r.nextFloat()*.4),size,color,dark));}
    @SubscribeEvent public static void tick(net.minecraftforge.event.TickEvent.ClientTickEvent event){if(event.phase!=net.minecraftforge.event.TickEvent.Phase.END)return;reset();if(Minecraft.getInstance().level==null||Minecraft.getInstance().isPaused())return;ORBITS.keySet().removeIf(t->t.isRemoved()||!t.formed);WISPS.forEach(ColoredWisp::tick);WISPS.removeIf(p->!p.isAlive());}
    @SubscribeEvent public static void render(net.minecraftforge.client.event.RenderLevelStageEvent event){if(event.getStage()!=net.minecraftforge.client.event.RenderLevelStageEvent.Stage.AFTER_PARTICLES)return;reset();var buffers=Minecraft.getInstance().renderBuffers().bufferSource();for(boolean dark:new boolean[]{false,true}){var type=dark?tc4revival.client.TCRenderTypes.sharpTranslucent(ProtectorEffects.TEXTURE):tc4revival.client.TCRenderTypes.runes(ProtectorEffects.TEXTURE);var out=buffers.getBuffer(type);for(var particle:WISPS)if(particle.dark==dark)particle.render(out,event.getCamera(),event.getPartialTick());buffers.endBatch(type);}}
    public static class ColoredWisp extends ProtectorEffects.Wisp {public final boolean dark;public ColoredWisp(net.minecraft.client.multiplayer.ClientLevel level,Vec3 from,Vec3 to,float size,int color,boolean dark){super(level,from,to,size,-.04f);this.dark=dark;rCol=dark?random.nextFloat()*.1f:(color>>16&255)/255f;gCol=dark?random.nextFloat()*.1f:(color>>8&255)/255f;bCol=dark?random.nextFloat()*.1f:(color&255)/255f;if(!dark&&rCol==0)rCol=1;}}
    public static class Orbits {protected final Vec3[] axes=new Vec3[3];protected final int[] periods=new int[3],offsets=new int[3];protected final double[] radii=new double[3];protected int age;protected long lastSeen;public Orbits(AuraPylonEntity tile){var random=tile.getLevel().random;for(int i=0;i<3;i++){axes[i]=new Vec3(random.nextDouble()*2-1,random.nextDouble(),random.nextDouble()*2-1).normalize();periods[i]=60+random.nextInt(40);offsets[i]=random.nextInt(80);radii[i]=2+random.nextDouble();}}public Vec3 point(int i,Vec3 center){var axis=axes[i];var radial=(axis.z==0?new Vec3(axis.y,-axis.x,0):new Vec3(0,axis.z,-axis.y)).normalize();double angle=Math.PI*2*((age+offsets[i])%periods[i])/(double)periods[i];return center.add(radial.scale(Math.cos(angle)).add(axis.cross(radial).scale(Math.sin(angle))).scale(radii[i]));}}
}
